<?php require_once __DIR__.'/bootstrap.php';auth();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$q=db()->prepare('SELECT password_hash FROM noora_admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$hash=$q->fetchColumn();$old=$_POST['old']??'';$new=$_POST['new']??'';if(!$hash||!password_verify($old,$hash))$err='رمز فعلی اشتباه است.';elseif(strlen($new)<12)$err='رمز جدید حداقل ۱۲ کاراکتر باشد.';elseif($new!==($_POST['confirm']??''))$err='تکرار رمز یکسان نیست.';else{$q=db()->prepare('UPDATE noora_admins SET password_hash=? WHERE id=?');$q->execute([password_hash($new,PASSWORD_DEFAULT),$_SESSION['admin_id']]);$msg='رمز تغییر کرد.';}}head('تغییر رمز');if($msg)echo '<p class="success">'.h($msg).'</p>';if($err)echo '<p class="error">'.h($err).'</p>';?><section class="panel narrow"><form method="post"><input type="hidden" name="csrf" value="<?=h(token())?>"><label>رمز فعلی</label><input type="password" name="old" required><label>رمز جدید (حداقل ۱۲ کاراکتر)</label><input type="password" name="new" minlength="12" required><label>تکرار رمز جدید</label><input type="password" name="confirm" minlength="12" required><button class="btn">تغییر رمز ←</button></form></section><?php foot();?>
